public class ApplicationSubmissionHelper {

    private static final String FILE_PATH_REGEX = "([a-zA-Z~])?(\\/[a-zA-Z0-9_.-]+)+\\/?";

    public static Map<String, String> getSparkConf(
            String submissionId,
            SubmitApplicationRequest request,
            AppConfig appConfig,
            AppConfig.SparkCluster sparkCluster) {

        Map<String, String> sparkConf = null;
        Map<String, String> defaultSparkConf = appConfig == null ? null : appConfig.getDefaultSparkConf();
        Map<String, String> fixedSparkConf = appConfig == null ? null : appConfig.getFixedSparkConf();

        if (defaultSparkConf != null) {
            if (sparkConf == null) {
                sparkConf = new HashMap<>();
            }
            Map<String, String> filteredDefaultSparkConf = applyFeatureGate(request, defaultSparkConf);

            for (Map.Entry<String, String> entry : filteredDefaultSparkConf.entrySet()) {
                sparkConf.put(entry.getKey(), substitutionSparkConfigValue(entry.getValue(), submissionId));
            }
        }

        if (sparkCluster != null && sparkCluster.getSparkConf() != null) {
            if (sparkConf == null) {
                sparkConf = new HashMap<>();
            }
            for (Map.Entry<String, String> entry : sparkCluster.getSparkConf().entrySet()) {
                sparkConf.put(entry.getKey(), substitutionSparkConfigValue(entry.getValue(), submissionId));
            }
        }

        if (request != null && request.getSparkConf() != null) {
            if (sparkConf == null) {
                sparkConf = new HashMap<>();
            }
            for (Map.Entry<String, String> entry : request.getSparkConf().entrySet()) {
                sparkConf.put(entry.getKey(), entry.getValue());
            }
        }

        if (fixedSparkConf != null) {
            if (sparkConf == null) {
                sparkConf = new HashMap<>();
            }
            sparkConf.putAll(fixedSparkConf);
        }

        if (request != null && !StringUtils.isEmpty(request.getApplicationName())) {
            if (sparkConf == null) {
                sparkConf = new HashMap<>();
            }
            sparkConf.put(SparkConstants.SPARK_APP_NAME_CONFIG, request.getApplicationName());
        }

        return sparkConf;
    }

    // included minimal feature gate behavior: in original code this filters based on request features.
    private static Map<String, String> applyFeatureGate(SubmitApplicationRequest request, Map<String, String> defaults) {
        // For testing purposes, return the defaults unchanged.
        return defaults;
    }

    private static String substitutionSparkConfigValue(String value, String submissionId) {
        if (value != null) {
            value = value.replace(Constants.SPARK_APPLICATION_RESOURCE_NAME_VAR, submissionId);
        }
        return value;
    }
}

/* Test class */
class ApplicationSubmissionHelperTest {

    @Test
    void testGetSparkConf_allNulls_returnsNull() {
        SubmitApplicationRequest request = new SubmitApplicationRequest();
        request.setApplicationName(null);
        request.setSparkConf(null);

        AppConfig appConfig = new AppConfig();
        appConfig.setDefaultSparkConf(null);
        appConfig.setFixedSparkConf(null);

        AppConfig.SparkCluster cluster = new AppConfig.SparkCluster();
        cluster.setSparkConf(null);

        Map<String, String> result = ApplicationSubmissionHelper.getSparkConf("submission-1", request, appConfig, cluster);
        assertNull(result, "When no configs provided, expected null map");
    }

    @Test
    void testGetSparkConf_mergingOrder_substitution_and_overrides() {
        String submissionId = "my-sub";

        // defaultSparkConf: key d1 includes placeholder that should be substituted
        Map<String, String> defaultConf = new HashMap<>();
        defaultConf.put("d1", Constants.SPARK_APPLICATION_RESOURCE_NAME_VAR + "_X");
        defaultConf.put("k", "defaultK");

        // cluster conf: overrides d1, and has c1 containing placeholder
        Map<String, String> clusterConf = new HashMap<>();
        clusterConf.put("d1", "clusterOverride");
        clusterConf.put("c1", Constants.SPARK_APPLICATION_RESOURCE_NAME_VAR + "_C");

        // request conf: overrides c1, defines r1
        Map<String, String> requestConf = new HashMap<>();
        requestConf.put("c1", "reqOverrideC");
        requestConf.put("r1", "reqVal");

        // fixed conf: overrides r1 and adds fixed key
        Map<String, String> fixedConf = new HashMap<>();
        fixedConf.put("r1", "fixedOverrideReq");
        fixedConf.put("fixed", "fixedVal");

        AppConfig appConfig = new AppConfig();
        appConfig.setDefaultSparkConf(defaultConf);
        appConfig.setFixedSparkConf(fixedConf);

        AppConfig.SparkCluster cluster = new AppConfig.SparkCluster();
        cluster.setSparkConf(clusterConf);

        SubmitApplicationRequest request = new SubmitApplicationRequest();
        request.setSparkConf(requestConf);
        request.setApplicationName("myAppName");

        Map<String, String> result = ApplicationSubmissionHelper.getSparkConf(submissionId, request, appConfig, cluster);
        assertNotNull(result, "Resulting sparkConf should not be null when some config provided");

        // d1: default set then cluster overrides it
        assertEquals("clusterOverride", result.get("d1"), "cluster should override default for key d1");

        // c1: cluster sets substituted value then request overrides it
        assertEquals("reqOverrideC", result.get("c1"), "request should override cluster for key c1");

        // r1: request sets value then fixed overrides it
        assertEquals("fixedOverrideReq", result.get("r1"), "fixed should override request for key r1");

        // fixed present
        assertEquals("fixedVal", result.get("fixed"), "fixed key should be present with fixed value");

        // k from default
        assertEquals("defaultK", result.get("k"), "default-only key should be present");

        // spark.app.name should be set from applicationName
        assertEquals("myAppName", result.get(SparkConstants.SPARK_APP_NAME_CONFIG), "applicationName should be inserted as spark.app.name");
    }

    @Test
    void testSubstitutionSparkConfigValue_privateMethod_viaReflection() throws NoSuchMethodException, InvocationTargetException, IllegalAccessException {
        Method method = ApplicationSubmissionHelper.class.getDeclaredMethod("substitutionSparkConfigValue", String.class, String.class);
        method.setAccessible(true);

        // null input should return null
        Object resNull = method.invoke(null, (String) null, "id");
        assertNull(resNull);

        // substitution should occur
        String template = "prefix-" + Constants.SPARK_APPLICATION_RESOURCE_NAME_VAR + "-suffix";
        Object res = method.invoke(null, template, "SUB123");
        assertTrue(res instanceof String);
        assertEquals("prefix-SUB123-suffix", res);
    }
}

